class GammaLUT
{
public:
    GammaLUT(float gamma)
    {
        for (unsigned int i = 0; i <= 255; i++)
        {
            lut[i] = (unsigned char)(255.f * powf(i / 255.f, gamma));
        }
    }

    unsigned char Lookup(unsigned char in)
    {
        assert(in <= 255);
        return lut[in];
    }
private:
    unsigned char lut[256];
};

