{
    ccl::Shader *shader = scene->create_node<ccl::Shader>();
    std::unique_ptr<ccl::ShaderGraph> graph = std::make_unique<ccl::ShaderGraph>();
    shader->set_graph(std::move(graph));
    shader->tag_update(scene);
    return shader;
}

